import socket,struct,json,pathlib,time
def execute(host,port,mac):
    import secrets,ipaddress
    if not isinstance(mac,bytes) or len(mac)!=6:raise ValueError('MAC must be six bytes')
    xid=secrets.randbits(32);request=bytearray(240);struct.pack_into('!BBBBIHH',request,0,1,1,6,0,xid,0,0x8000);request[28:34]=mac;request[236:240]=b'\x63\x82\x53\x63';request.extend(b'\x35\x01\x01\x37\x03\x01\x03\x06\xff');request.extend(b'\0'*(300-len(request)))
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as sock:sock.settimeout(2);sock.connect((host,port));sock.send(request);data=sock.recv(4096)
    if len(data)<240 or data[:3]!=b'\2\1\6' or struct.unpack('!I',data[4:8])[0]!=xid or data[28:34]!=mac or data[236:240]!=b'\x63\x82\x53\x63':raise ValueError('offer not associated with request')
    options={};pos=240;ended=False
    while pos<len(data):
        kind=data[pos];pos+=1
        if kind==0:continue
        if kind==255:ended=True;break
        if pos>=len(data):raise ValueError('missing option length')
        size=data[pos];pos+=1
        if pos+size>len(data):raise ValueError('truncated option')
        if kind in [53,54,51] and kind in options:raise ValueError('duplicate critical option')
        options[kind]=data[pos:pos+size];pos+=size
    if not ended or options.get(53)!=b'\2' or len(options.get(54,b''))!=4 or len(options.get(51,b''))!=4 or ipaddress.IPv4Address(data[16:20]).is_unspecified or ipaddress.IPv4Address(data[16:20]).is_multicast or data[16:20]==b'\xff'*4:raise ValueError('invalid offer fields')
    return {'address':str(ipaddress.IPv4Address(data[16:20])),'server':str(ipaddress.IPv4Address(options[54])),'lease_seconds':struct.unpack('!I',options[51])[0]}
```

