import socket,struct,json,pathlib,time
def execute(host,port,name):
    import secrets
    labels=name.rstrip('.').encode('ascii').split(b'.')
    if not labels or any(not 1<=len(x)<=63 for x in labels):raise ValueError('invalid name')
    wire=b''.join(bytes([len(x)])+x for x in labels)+b'\0'
    if len(wire)>255:raise ValueError('name too long')
    xid=secrets.randbelow(65536);query=struct.pack('!HHHHHH',xid,0x100,1,0,0,0)+wire+struct.pack('!HH',15,1)
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as sock:sock.settimeout(2);sock.connect((host,port));sock.send(query);data=sock.recv(65535)
    if len(data)<12:raise ValueError('short DNS')
    ident,flags,qd,an,_,_=struct.unpack('!HHHHHH',data[:12])
    if ident!=xid or not flags&0x8000 or flags&0x20f:raise ValueError('DNS error')
    def read_name(pos):
        labels=[];seen=set();end=None
        while True:
            if pos>=len(data) or pos in seen:raise ValueError('bad name pointer')
            seen.add(pos);size=data[pos]
            if size&0xc0==0xc0:
                if pos+1>=len(data):raise ValueError('short pointer')
                if end is None:end=pos+2
                pos=((size&63)<<8)|data[pos+1];continue
            if size&0xc0:raise ValueError('bad label')
            pos+=1
            if size==0:return '.'.join(labels).lower()+'.',end if end is not None else pos
            if pos+size>len(data):raise ValueError('short label')
            labels.append(data[pos:pos+size].decode('ascii'));pos+=size
    pos=12
    for _ in range(qd):_,pos=read_name(pos);pos+=4
    out=[]
    for _ in range(an):
        _,pos=read_name(pos)
        if pos+10>len(data):raise ValueError('short RR')
        kind,cls,ttl,size=struct.unpack('!HHIH',data[pos:pos+10]);pos+=10;end=pos+size
        if end>len(data):raise ValueError('short RDATA')
        if kind==15 and cls==1:
            if size<3:raise ValueError('short MX')
            preference=struct.unpack('!H',data[pos:pos+2])[0];exchange,consumed=read_name(pos+2)
            if consumed!=end:raise ValueError('MX size mismatch')
            out.append({'preference':preference,'exchange':exchange})
        pos=end
    return sorted(out,key=lambda x:(x['preference'],x['exchange']))
