import socket,struct,json,pathlib,time
def execute(pcap_path,report_path):
    data=pathlib.Path(pcap_path).read_bytes()
    if len(data)<24:raise ValueError('short global header')
    endian={b'\xd4\xc3\xb2\xa1':'<',b'\xa1\xb2\xc3\xd4':'>'}.get(data[:4])
    if endian is None:raise ValueError('unsupported capture format')
    major,minor,zone,sigfigs,snaplen,link=struct.unpack(endian+'HHiIII',data[4:24])
    if (major,minor)!=(2,4) or link!=1 or not 0<snaplen<=16777216:raise ValueError('unsupported pcap header')
    pos=24;out=[]
    while pos<len(data):
        if pos+16>len(data):raise ValueError('short record header')
        sec,usec,included,original=struct.unpack(endian+'IIII',data[pos:pos+16]);pos+=16
        if usec>=1000000 or included>snaplen or included>original or pos+included>len(data):raise ValueError('invalid record length/time')
        packet=data[pos:pos+included];pos+=included;out.append({'captured':included,'original':original,'truncated':included<original,'ethertype':int.from_bytes(packet[12:14],'big') if included>=14 else None})
    pathlib.Path(report_path).write_text(json.dumps(out,sort_keys=True),encoding='utf-8');return out
