import socket,struct,json,pathlib,time
def execute(host,port,name,search,ndots):
    import secrets
    if type(ndots) is not int or not 0<=ndots<=15:raise ValueError('invalid ndots')
    absolute=name.endswith('.');base=name.rstrip('.')
    options=[base] if absolute else ([base]+[base+'.'+x.rstrip('.') for x in search] if base.count('.')>=ndots else [base+'.'+x.rstrip('.') for x in search]+[base])
    candidates=list(dict.fromkeys(options));encoded=[]
    for candidate in candidates:
        labels=candidate.encode('ascii').split(b'.')
        if any(not 1<=len(x)<=63 for x in labels):raise ValueError('invalid name')
        wire=b''.join(bytes([len(x)])+x for x in labels)+b'\0'
        if len(wire)>255:raise ValueError('name too long')
        encoded.append(wire)
    queries=[]
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as sock:
        sock.settimeout(2);sock.connect((host,port))
        for candidate,wire in zip(candidates,encoded):
            ident=secrets.randbelow(65536);query=struct.pack('!HHHHHH',ident,0x100,1,0,0,0)+wire+struct.pack('!HH',1,1);queries.append(candidate);sock.send(query);data=sock.recv(4096)
            if len(data)<12 or data[:2]!=query[:2] or not data[2]&0x80 or data[2]&2:raise ValueError('invalid DNS response')
            rcode=data[3]&15
            if rcode==0:return {'selected':candidate,'queries':queries}
            if rcode!=3:raise ValueError('DNS failure is not NXDOMAIN')
    return {'selected':None,'queries':queries}
