import socket,struct,json,pathlib,time
def execute(host,port,name,cache,now):
    import secrets
    key=name.rstrip('.').lower();old=cache.get(key)
    if old and now<old['expires']:return {'address':old['address'],'remaining':old['expires']-now,'source':'cache'}
    labels=key.encode('ascii').split(b'.')
    if any(not 1<=len(x)<=63 for x in labels):raise ValueError('invalid name')
    wire=b''.join(bytes([len(x)])+x for x in labels)+b'\0';ident=secrets.randbelow(65536);query=struct.pack('!HHHHHH',ident,0x100,1,0,0,0)+wire+struct.pack('!HH',1,1)
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as s:s.settimeout(2);s.connect((host,port));s.send(query);data=s.recv(4096)
    if len(data)<12 or data[:2]!=query[:2]:raise ValueError('bad DNS')
    flags,qd,an,ns,ar=struct.unpack('!HHHHH',data[2:12]);offset=len(query)
    if flags&0x820f!=0x8000 or (qd,an)!=(1,1) or data[12:offset]!=query[12:] or len(data)!=offset+16 or data[offset:offset+2]!=b'\xc0\x0c':raise ValueError('unsupported answer')
    kind,cls,ttl,size=struct.unpack('!HHIH',data[offset+2:offset+12])
    if (kind,cls,size)!=(1,1,4):raise ValueError('not A')
    address=socket.inet_ntoa(data[-4:]);cache[key]={'address':address,'expires':now+ttl};return {'address':address,'remaining':ttl,'source':'dns'}
