import socket,struct,json,pathlib,time
def execute(listener,upstream_host,upstream_port):
    import http.client
    conn,peer=listener.accept()
    with conn:
        conn.settimeout(2);data=b''
        while b'\r\n\r\n' not in data:
            part=conn.recv(4096)
            if not part:raise EOFError('headers truncated')
            data+=part
            if len(data)>16384:raise ValueError('header limit')
        header,extra=data.split(b'\r\n\r\n',1);lines=header.decode('iso-8859-1').split('\r\n');method,path,version=lines[0].split(' ')
        if method!='GET' or version!='HTTP/1.1' or not path.startswith('/') or path.startswith('//') or extra:raise ValueError('unsupported request')
        hosts=[]
        for line in lines[1:]:
            key,value=line.split(':',1);key=key.lower();value=value.strip()
            if key=='host':hosts.append(value)
            if key=='transfer-encoding' or key=='content-length' and value!='0':raise ValueError('body not supported')
        if len(hosts)!=1 or not hosts[0]:raise ValueError('ambiguous host')
        upstream=http.client.HTTPConnection(upstream_host,upstream_port,timeout=2)
        try:
            upstream.request('GET',path,headers={'Host':hosts[0],'X-Forwarded-Proto':'http','X-Forwarded-For':peer[0],'Connection':'close'});res=upstream.getresponse();body=res.read();status=res.status
        finally:upstream.close()
        conn.sendall(('HTTP/1.1 '+str(status)+' Result\r\nContent-Length: '+str(len(body))+'\r\nConnection: close\r\n\r\n').encode()+body)
