import socket,struct,json,pathlib,time
def execute(host,port,payload,timeout):
    if isinstance(timeout,bool) or not isinstance(timeout,(int,float)) or not .01<=timeout<=1:raise ValueError('invalid timeout')
    with socket.socket(socket.AF_INET,socket.SOCK_DGRAM) as sock:
        sock.settimeout(timeout);sock.connect((host,port));sock.send(payload)
        try:response=sock.recv(65535)
        except socket.timeout:return {'state':'unknown','payload':None}
        except ConnectionRefusedError:return {'state':'refused','payload':None}
        return {'state':'responded','payload':response}
```

