import socket,time,io,http.client

def execute(host,port,path):
    if not path.startswith('/') or path.startswith('//') or any(c in path for c in '\r\n'):
        raise ValueError('invalid path')
    deadline=time.monotonic()+1.0
    def remaining():
        value=deadline-time.monotonic()
        if value<=0:raise TimeoutError('total connection/read deadline exceeded')
        return value
    try:conn=socket.create_connection((host,port),timeout=remaining())
    except ConnectionRefusedError:return {'tcp':False,'http':False,'error':'refused'}
    except TimeoutError:return {'tcp':False,'http':False,'error':'timeout'}
    class DeadlineReader(io.RawIOBase):
        def readable(self):return True
        def readinto(self,target):
            conn.settimeout(remaining())
            return conn.recv_into(target)
    class ResponseSocket:
        def makefile(self,mode):return io.BufferedReader(DeadlineReader())
    response=None
    with conn:
        try:
            conn.settimeout(remaining())
            conn.sendall(('GET '+path+' HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n').encode('ascii'))
            response=http.client.HTTPResponse(ResponseSocket());response.begin();body=response.read()
            remaining()
            return {'tcp':True,'http':True,'status':response.status,'body':body}
        except TimeoutError:return {'tcp':True,'http':False,'error':'timeout'}
        except (http.client.HTTPException,ConnectionError):return {'tcp':True,'http':False,'error':'protocol'}
        finally:
            if response is not None:response.close()
```

以monotonic记录一个绝对截止时间，建连、发送和每次底层读取都只使用剩余预算。HTTPResponse内部可能多次读取，不能仅在开始read前设置一次socket超时；自定义RawIOBase在每次recv_into前更新剩余时间。资源在finally及连接上下文中关闭。

原理补充（历史保留）：TCP连接成功不代表HTTP协议与业务正常；503仍是可解析的HTTP响应，协议错误、连接拒绝和总期限超时分别记录。

